        count[(x, y)] = count.get((x, y), 0) + 1
        column = columns.setdefault(x, {})
        column[y] = column.get(y, 0) + 1
    else:
        total = 0
        for y2, c in columns.get(x, {}).items():
            if y2 != y:
                d = abs(y2 - y)
                for dx in (d, -d):
                    total += c * count.get((x + dx, y), 0) * count.get((x + dx, y2), 0)
        out.append(total)
